```typescript
export function projectContextMiddleware(
  options: ProjectContextMiddlewareOptions = {}
) {
  const manager = new ProjectContextManager(
    options.startupProject,
    options.pubsub
  );

  // Register startup project if provided
  if (options.startupProject) {
    try {
      manager.registerProject(options.startupProject, true);
    } catch (error) {
      console.warn(`[daemon] Failed to register startup project: ${error}`);
    }
  }

  const middleware = (app: Elysia) =>
    app
      .state('projectManager', manager)
      .derive(async ({ request, set }) => {
        // Skip for /api/health and static files
        const url = new URL(request.url, `http://${request.headers.get('host')}`);
        const needsProject = url.pathname.startsWith('/api/') 
          && url.pathname !== '/api/health';
        if (!needsProject) {
          return { projectContext: undefined as unknown as ProjectContext };
        }

        try {
          const projectPath = request.headers.get('X-Kspec-Dir') || undefined;
          let projectContext: ProjectContext;

          if (projectPath) {
            try {
              projectContext = manager.getProject(projectPath);
            } catch (err) {
              projectContext = manager.registerProject(projectPath);
              void manager.startWatcher(projectPath).catch(e => {
                console.error(`[daemon] Failed to start watcher: ${e}`);
              });
            }
          } else {
            projectContext = manager.getProject();  // uses default
          }

          return { projectContext };
        } catch (err: any) {
          const message = err.message;
          // ... error handling with appropriate status codes ...
          if (message.includes('No default project configured')) {
            set.status = 400;
            return { error: message };
          }
          // ... more error cases ...
        }
      });

  return { manager, middleware };
}
```

**Server Registration:**
```typescript
// packages/daemon/src/server.ts
const { manager: projectContextManager, middleware: projectMiddleware } = 
  projectContextMiddleware({
    startupProject: startupProjectPath,
    pubsub: pubsubManager
  });

app.use(projectMiddleware)
   .get('/api/health', () => ({ /* ... */ }))
   .use(createTasksRoutes({ pubsub: pubsubManager }))
   // ... other routes ...
```

**Route Usage:**
```typescript
// In route handlers
.get('/', async ({ query, projectContext }) => {
  // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
  const ctx = await initContext(projectContext.path);
  // ... rest of handler ...
})
```

